parameters.jsCode:
// Un seul flux par tour de boucle : on étiquette chaque article avec son sujet et son flux
let src = {};
try { src = $('Loop Over Items').item.json; } catch (e) {}
return { json: { ...$json, topic_slug: src.topic_slug || null, feed_url: src.url || null } };

// Décode les entités HTML (&#8217; &amp; …) et retire les balises résiduelles
const decode = (s = '') => String(s)
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
  .replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&nbsp;/g, ' ')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')
  .replace(/<[^>]*>/g, '')
  .replace(/\s+/g, ' ').trim();

const since = Date.now() - 24 * 3600 * 1000;   // fraîcheur : dernières 24h
const fetchedAt = new Date().toISOString();
const seen = new Set();
const out = [];

for (const { json: a } of $input.all()) {
  if (!a.link || !a.topic_slug || seen.has(a.link)) continue;   // erreur, flux vide, ou doublon
  const date = new Date(a.isoDate || a.pubDate);
  if (isNaN(date) || date < since) continue;                     // sans date ou trop ancien
  seen.add(a.link);
  out.push({ json: {
    url: a.link,
    title: decode(a.title),
    description: decode(a.contentSnippet || a.content || a.description).slice(0, 500),
    source: (a.link.match(/^https?:\/\/(?:www\.)?([^\/]+)/) || [])[1] || '',
    topic_slug: a.topic_slug,
    published_at: date.toISOString(),
    fetched_at: fetchedAt,
  }});
}
return out;

